.pill {
    display: inline-flex;
    line-height: 1;
    text-decoration: none;
    color: $color-nearblack;
    font-size: $font-size--icon;
    border: solid $border-width-hairline $color-nearblack;
    border-radius: $border-radius-round;
    padding: calc(#{$measure--half} -1px) $measure--threequarters $measure--half
        $measure--threequarters; //Shim on top padding to allow for character height so text looks centered.
    min-width: 90px;
    justify-content: space-around;
    gap: $measure--half;
    & + & {
        margin-left: $measure--half;
    }
    &:visited {
        color: inherit;
    }
    &:focus {
        color: $color-nearblack;
    }
    &--active,
    &:hover {
        border-color: $color-red50;
        background: $color-red50;
        color: $color-purewhite;
        border: solid $border-width-hairline $color-red50;
    }
    &--active {
        &:focus {
            background: $color-red50;
            color: $color-purewhite;
            border: solid $border-width-hairline $color-red50;
        }
        &:after {
            font: var(--fa-font-regular);
            content: fa-content($fa-var-check);
        }
    }

    article & {
        //Styles to overwrite generic `article a` styles.
        &:visited {
            border: solid $border-width-hairline $color-nearblack;
        }
        &--active {
            &:visited {
                color: $color-purewhite;
                border: solid $border-width-hairline $color-red50;
            }
        }
        &:hover {
            color: $color-purewhite;
            border: solid $border-width-hairline $color-red50;
        }
    }
}
